sys_script.script:
(function executeRule(current, previous) {
    var calc = new x_2298436_snackf_0.SnackFlowCalc()

    var productionOrderId = current.getValue('production_order')
    if (productionOrderId) {
        // Touches existing prod_cost rows so their BEFORE rule fully recomputes
        // them. Never creates a prod_cost row.
        calc.recalcProdCostForOrder(productionOrderId)
    }

    // Consumption line moved to another production order: refresh the old one.
    if (previous) {
        var previousProductionOrderId = previous.getValue('production_order')
        if (previousProductionOrderId && previousProductionOrderId !== productionOrderId) {
            calc.recalcProdCostForOrder(previousProductionOrderId)
        }
    }
})(current, previous)
